ptions."}}}, "hasFullSchema": true}, "GMAIL_FETCH_MESSAGE_BY_MESSAGE_ID": {"toolkit": "GMAIL", "tool_slug": "GMAIL_FETCH_MESSAGE_BY_MESSAGE_ID", "description": "Fetches a specific email message by its ID, provided the `message_id` exists and is accessible to the authenticated `user_id`. Spam/trash messages are excluded unless upstream list/search calls used `include_spam_trash=true`. Use `internalDate` (milliseconds since epoch) rather than header `Date` for recency checks.", "input_schema": {"type": "object", "required": ["message_id"], "properties": {"format": {"type": "string", "default": "full", "examples": ["metadata", "minimal", "full", "raw"], "description": "Format for message content. 'minimal': lightest (ID, thread ID, labels only). 'metadata': headers and message metadata without body content - ideal for summarization, analysis, or when you only need subject/sender/timestamp (recommended for most use cases). 'full': complete MIME structure with 50+ headers, nested parts, and base64url-encoded body data - heavy payload, only use when you need the complete raw MIME structure for parsing attachments or body content. 'raw': entire RFC 2822 formatted message as base64url string."}, "user_id": {"type": "string", "default": "me", "examples": ["user@example.com", "me"], "description": "User's email address or 'me' for the authenticated user."}, "message_id": {"type": "string", "examples": ["19b11732c1b578fd", "18c5e5b5f5d5e5b5", "1736ccf5d7b4d452"], "minLength": 1, "description": "The Gmail API message ID (hexadecimal string, typically 15-16 characters like '19b11732c1b578fd'). Must be obtained from Gmail API responses (e.g., List Messages, Search Messages). Do NOT use email subjects, dates, sender names, or custom identifiers. Do NOT use `threadId` (use GMAIL_FETCH_MESSAGE_BY_THREAD_ID for threads), the Message-ID email header, or any fabricated value — only IDs from Gmail API list/search responses."}}}, "hasFullSchema": true}, "GMAIL_BATCH_MODIFY_MESSAGES": {"t